def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    if not alive:
        safe = min(budget, DAILY_SALARY * 0.35)
        return max(0, safe)

    total_players = 1 + len(alive)
    expected_competitors_served = max(1, int(supply // WATER_REQ))
    scarcity = total_players - expected_competitors_served

    prev_bids = []
    desperate_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 1.2:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_opp += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2

    if scarcity >= 2:
        urgency += 2
    elif scarcity >= 1:
        urgency += 1

    if desperate_opp >= max(1, len(alive) // 2):
        urgency += 1

    if budget < DAILY_SALARY:
        urgency -= 1

    if urgency <= 0:
        bid = max(8, DAILY_SALARY * 0.22)
    elif urgency == 1:
        bid = max(14, DAILY_SALARY * 0.32)
    elif urgency == 2:
        bid = max(22, DAILY_SALARY * 0.48)
    elif urgency == 3:
        bid = max(32, DAILY_SALARY * 0.62)
    elif urgency == 4:
        bid = max(42, DAILY_SALARY * 0.78)
    else:
        bid = max(52, DAILY_SALARY * 0.93)

    if highest_prev > 0:
        if scarcity >= 1 or urgency >= 3:
            target = highest_prev + 2
            if target > bid:
                bid = target
        else:
            soft_target = avg_prev + 1
            if soft_target > bid * 0.8:
                bid = max(bid, soft_target)

    if supply >= WATER_REQ * total_players:
        bid = min(bid, DAILY_SALARY * 0.4)
    elif supply <= WATER_REQ * max(1, total_players - 2):
        bid += 6

    if rich_opp >= len(alive) and urgency <= 1:
        bid = min(bid, DAILY_SALARY * 0.28)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, DAILY_SALARY * 0.9)

    bid = min(bid, budget)
    if bid < 0:
        bid = 0
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Collect alive opponents and their immediate (yesterday) behavior
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents, bid modestly
    if not alive_opps:
        target = min(my_status['budget'], DAILY_SALARY * 0.4)
        return max(0.0, float(target))

    # Immediate reaction to yesterday's bidding pressure
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Base bid: mid-range to beat cautious bidders but avoid overpaying
    # Use supply estimate to choose a bid that is likely to secure enough water.
    # We can't control allocation directly, but higher bids correlate with winning water.
    supply_ratio = supply / float(WATER_REQ)
    # Heuristic: if supply is near minimum, competition is tighter -> bid higher.
    if supply <= float(MIN_SUPPLY) + 0.5:
        base = DAILY_SALARY * 0.62
    elif supply >= float(MAX_SUPPLY) - 0.5:
        base = DAILY_SALARY * 0.48
    else:
        base = DAILY_SALARY * 0.55

    # Pressure adjustment from yesterday
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If someone bid very aggressively yesterday, we slightly overbid to prevent being starved.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status.get('hp', 0) > 3:
                base = max(base, DAILY_SALARY * 0.66)
            else:
                base = max(base, DAILY_SALARY * 0.92)
        # If bids were low, we can bid just enough.
        elif highest_prev_bid <= DAILY_SALARY * 0.45:
            base = min(base, DAILY_SALARY * 0.52)

    # Survival safeguard: if low hp or many no-water days, bid more.
    hp = float(my_status.get('hp', 0))
    no_water_days = int(my_status.get('no_water_days', 0))
    if hp <= 2 or no_water_days >= 2:
        base = max(base, DAILY_SALARY * 0.9)
    elif hp <= 3:
        base = max(base, DAILY_SALARY * 0.72)

    # Budget cap and non-negative
    budget = float(my_status.get('budget', 0))
    bid = min(budget, base)

    # Keep bid within plausible range
    if bid < 0.0:
        bid = 0.0

    return float(bid)
